html:
{% set r = get_results(doc.name) %}
<h2>{{ doc.title | e }} — Results</h2>
<p>
	Turnout: {{ r.voted }} of {{ r.total }} voted{% if r.total %} ({{ (100 * r.voted / r.total) | round(1) }}%){% endif %}
</p>

{% for p in r.positions %}
<h4 style="margin-top: 24px;">{{ p.position | e }}</h4>
<table class="table table-bordered">
	<thead>
		<tr><th>Candidate</th><th style="width: 20%;">Votes</th><th style="width: 25%;">Result</th></tr>
	</thead>
	<tbody>
	{% for c in p.candidates %}
		<tr{% if c.name == p.winner %} style="font-weight: bold;"{% endif %}>
			<td>{{ c.full_name | e }}</td>
			<td>{{ c.votes }}</td>
			<td>{% if c.name == p.winner %}Winner{% elif c.name in p.tied %}Tie{% endif %}</td>
		</tr>
	{% endfor %}
	</tbody>
</table>
{% if p.tied and p.winner %}
	<p>TIE — winner chosen by committee: {% for c in p.candidates if c.name == p.winner %}{{ c.full_name | e }}{% endfor %}</p>
{% elif p.tied %}
	<p>TIE — unresolved</p>
{% elif not p.winner %}
	<p>No votes</p>
{% endif %}
{% endfor %}
